<?php
namespace App\Http\Controllers; use App\Models\Facility; use Illuminate\Http\Request;
class FacilityController extends Controller { public function index(){return Facility::with(['inspections','complaints'])->get();} public function store(Request $r){$data=$r->validate(['name'=>'required|string|max:150','location'=>'required|string|max:150','cleanliness_score'=>'nullable|numeric|between:0,10','water_availability'=>'boolean']);return response()->json(Facility::create($data),201);} public function show(Facility $facility){return $facility->load(['inspections','complaints']);} public function update(Request $r,Facility $facility){$data=$r->validate(['name'=>'sometimes|required|string|max:150','location'=>'sometimes|required|string|max:150','cleanliness_score'=>'nullable|numeric|between:0,10','water_availability'=>'boolean']);$facility->update($data);return $facility;} public function destroy(Facility $facility){$facility->delete();return response()->noContent();} }
